import { useState } from "react";
import api from "@/lib/api";
import { toast } from "sonner";
import { Link } from "react-router-dom";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";

export default function ForgotPassword() {
  const [email, setEmail] = useState(""); const [tok, setTok] = useState("");
  const submit = async (e) => {
    e.preventDefault();
    try { const { data } = await api.post("/auth/forgot-password", { email }); toast.success(data.message); if (data.reset_token_dev) setTok(data.reset_token_dev); }
    catch (err) { toast.error("Something went wrong"); }
  };
  return (
    <div className="max-w-md mx-auto px-4 py-14" data-testid="forgot-page">
      <h1 className="font-display text-3xl font-bold text-center">Forgot Password</h1>
      <form onSubmit={submit} className="bg-white border border-[#E6DFD5] rounded-2xl p-6 mt-6 card-shadow space-y-4">
        <Input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Enter your email" required data-testid="forgot-email" />
        <Button type="submit" className="btn-primary rounded-full w-full">Send Reset Link</Button>
        {tok && <Link to={`/reset-password?token=${tok}`} className="block text-xs text-center text-[#D97706] underline" data-testid="dev-reset-link">Dev: continue to reset</Link>}
      </form>
    </div>
  );
}
